#!/usr/bin/env bash
# A TEST-ONLY IDP-Dienst signer for the ti-idpd-client tests: a brainpoolP256r1 key and a
# self-signed C.FD.SIG-like certificate (role oid_idpd in an admission statement, as
# gematik's IDP certificates carry it). The tests sign discovery documents and
# challenges with it. The TEST-ONLY key idpd-sig.key is committed; a run writes only what is
# missing, FORCE=1 writes the certificate again from the same key (spec/fixtures.sh, and the
# test data rule of docs/design/testing.md). Nothing here is randomised.
set -euo pipefail
cd "$(dirname "$0")"
keys=$PWD
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
. ../../../../spec/fixtures.sh

ext=$work/ext.cnf
cat > "$ext" <<'CNF'
[idp_sig]
keyUsage = critical, digitalSignature
subjectKeyIdentifier = hash
1.3.36.8.3.3 = ASN1:SEQUENCE:admission_syntax

[admission_syntax]
contents = SEQUENCE:contents_of_admissions
[contents_of_admissions]
admissions = SEQUENCE:admissions
[admissions]
profession_infos = SEQUENCE:profession_infos
[profession_infos]
info = SEQUENCE:profession_info
[profession_info]
items = SEQUENCE:profession_items
oids = SEQUENCE:profession_oids
[profession_items]
item = UTF8String:IDP-Dienst
[profession_oids]
oid = OID:1.2.276.0.76.4.260
CNF

if [ ! -e idpd-sig.key ]; then
    key idpd-sig bp256
    # As SEC1 "EC PRIVATE KEY": what the tests decode.
    openssl ec -in idpd-sig.key -out "$work/sec1.key" 2>/dev/null
    mv "$work/sec1.key" idpd-sig.key
fi

if wanted idpd-sig.pem; then
    openssl req -new -key idpd-sig.key -subj "/C=DE/O=gematik TEST-ONLY/CN=IDP-Dienst Signer TEST-ONLY" \
        -out "$work/idpd-sig.csr"
    # shellcheck disable=SC2046 # sign_options prints whole options, one per line
    openssl x509 -req -in "$work/idpd-sig.csr" -key idpd-sig.key -set_serial "$(serial_of idpd-sig)" \
        -not_before 20260101000000Z -not_after 20310101000000Z \
        -extfile "$ext" -extensions idp_sig $(sign_options idpd-sig.key) -out idpd-sig.pem 2>/dev/null
fi

{
    echo "# Provenance"
    echo
    echo "Generated by generate.sh. TEST-ONLY material: a committed key and a self-signed certificate,"
    echo "no relation to any IDP."
    echo "Refresh: delete a file and run \`./generate.sh\`, or \`FORCE=1 ./generate.sh\` for the certificate again"
    echo "from the same key; the output is reproducible."
    echo
    echo "| File | SHA-256 |"
    echo "|---|---|"
    for f in idpd-sig.key idpd-sig.pem; do
        printf '| `%s` | `%s` |\n' "$f" "$(openssl dgst -sha256 -r "$f" | cut -d' ' -f1)"
    done
} > PROVENANCE.md
